import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    static Map<Integer, Long> memo1 = new HashMap<>();
    static Map<String, Long> memo2 = new HashMap<>();

    public static long countNum1(int k) {
        if (k < 0) {
            return 0;
        } else if (k < 2) {
            return 1;
        } else if (!memo1.containsKey(k)) {
            long totalSum = 0;
            for (int index = 0; index < k; index++) {
                totalSum += countNum1(index) * countNum1(k - 1 - index);
            }
            memo1.put(k, totalSum);
        }
        return memo1.get(k);
    }

    public static long countNum2(int k, int m) {
        if (k < 0 || m <= 0 || k >= Math.pow(2, m - 1)) {
            return 0;
        } else if (k < 2) {
            return 1;
        } else if (k < m) {
            return countNum1(k);
        } else {
            String key = k + "," + m;
            if (!memo2.containsKey(key)) {
                long totalSum = 0;
                for (int index = 0; index < k; index++) {
                    totalSum += countNum2(index, m - 1) * countNum2(k - 1 - index, m - 1);
                }
                memo2.put(key, totalSum);
            }
            return memo2.get(key);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int val1 = scanner.nextInt();
        int val2 = scanner.nextInt();
        System.out.println(countNum1(val1) - countNum2(val1, val2));
        scanner.close();
    }
}
